#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 long long minCost(vector<int>& basket1,vector<int>& basket2){
  map<int,int> diff;int globalMin=INT_MAX;
  for(int x:basket1){++diff[x];globalMin=min(globalMin,x);}
  for(int x:basket2){--diff[x];globalMin=min(globalMin,x);}
  vector<int> extra;
  for(auto p:diff){if(abs(p.second)%2)return -1;
   for(int j=0;j<abs(p.second)/2;++j)extra.push_back(p.first);
  }
  sort(extra.begin(),extra.end());long long ans=0;
  for(int i=0;i<(int)extra.size()/2;++i)ans+=min((long long)extra[i],2LL*globalMin);
  return ans;
 }
};
